<?php
/**
 * Media manager: persists generated bytes as media-library attachments with
 * alt text and provenance meta, and cleans up unchosen variations.
 *
 * @package Launchy_Illustrator
 */

namespace Launchy_Illustrator;

use WP_Error;

defined( 'ABSPATH' ) || exit;

/**
 * Attachment lifecycle for generated media.
 */
class Media_Manager {

	const GENERATED_META = '_launchy_generated';

	/**
	 * Save generated image bytes as an attachment.
	 *
	 * @param array    $image     {bytes, mime}.
	 * @param array    $placement Placement plan item.
	 * @param \WP_Post $post      Parent post.
	 * @param int      $variation 1-based variation index.
	 * @return int|WP_Error Attachment ID.
	 */
	public function save( array $image, array $placement, \WP_Post $post, $variation = 1 ) {
		require_once ABSPATH . 'wp-admin/includes/image.php';
		require_once ABSPATH . 'wp-admin/includes/file.php';
		require_once ABSPATH . 'wp-admin/includes/media.php';

		$ext      = 'image/jpeg' === $image['mime'] ? 'jpg' : 'png';
		$filename = sanitize_file_name(
			sprintf( '%s-%s-%s-v%d-%s.%s', $placement['media_type'], $post->post_name ? $post->post_name : $post->ID, $placement['role'], $variation, gmdate( 'Ymd-His' ), $ext )
		);

		$upload = wp_upload_bits( $filename, null, $image['bytes'] );
		if ( ! empty( $upload['error'] ) ) {
			return new WP_Error( 'launchy_upload_failed', $upload['error'] );
		}

		$attachment_id = wp_insert_attachment(
			array(
				'post_mime_type' => $image['mime'],
				'post_title'     => sprintf(
					/* translators: 1: image role (hero, banner...), 2: post title */
					__( 'Generated %1$s — %2$s', 'launchy-illustrator' ),
					$placement['role'],
					$post->post_title
				),
				'post_content'   => '',
				'post_status'    => 'inherit',
			),
			$upload['file'],
			$post->ID,
			true
		);

		if ( is_wp_error( $attachment_id ) ) {
			return $attachment_id;
		}

		wp_update_attachment_metadata( $attachment_id, wp_generate_attachment_metadata( $attachment_id, $upload['file'] ) );
		update_post_meta( $attachment_id, '_wp_attachment_image_alt', $placement['alt_text'] );
		update_post_meta(
			$attachment_id,
			self::GENERATED_META,
			array(
				'post_id'      => $post->ID,
				'placement_id' => $placement['id'],
				'role'         => $placement['role'],
				'variation'    => (int) $variation,
			)
		);

		return $attachment_id;
	}

	/**
	 * Delete unchosen generated variations. Only ever deletes attachments this
	 * plugin created (provenance meta required) for the given post.
	 *
	 * @param int   $post_id Post ID.
	 * @param array $ids     Attachment IDs to discard.
	 * @return int Number deleted.
	 */
	public function discard( $post_id, array $ids ) {
		$deleted = 0;
		foreach ( array_map( 'absint', $ids ) as $id ) {
			if ( ! current_user_can( 'delete_post', $id ) ) {
				continue;
			}
			$meta = get_post_meta( $id, self::GENERATED_META, true );
			if ( is_array( $meta ) && isset( $meta['post_id'] ) && (int) $meta['post_id'] === (int) $post_id ) {
				if ( wp_delete_attachment( $id, true ) ) {
					$deleted ++;
				}
			}
		}
		return $deleted;
	}
}
